"""Patch the platform folders generated by `flutter create` (run in CI)."""
import re, pathlib, sys

root = pathlib.Path(sys.argv[1] if len(sys.argv) > 1 else '.')
NAME = 'IPTV Player'

# ---------- Android ----------
m = root / 'android/app/src/main/AndroidManifest.xml'
if m.exists():
    s = m.read_text()
    if 'android.permission.INTERNET' not in s:
        s = s.replace('<application', '<uses-permission android:name="android.permission.INTERNET"/>\n    <application', 1)
    s = re.sub(r'android:label="[^"]*"', f'android:label="{NAME}"', s, count=1)
    if 'usesCleartextTraffic' not in s:
        s = s.replace('<application', '<application\n        android:usesCleartextTraffic="true"', 1)
    m.write_text(s)
    print('patched', m)

# ---------- iOS ----------
p = root / 'ios/Runner/Info.plist'
if p.exists():
    s = p.read_text()
    s = re.sub(r'(<key>CFBundleDisplayName</key>\s*<string>)[^<]*(</string>)', rf'\g<1>{NAME}\g<2>', s)
    extra = ''
    if 'NSAppTransportSecurity' not in s:
        extra += ('\t<key>NSAppTransportSecurity</key>\n\t<dict>\n\t\t<key>NSAllowsArbitraryLoads</key>\n\t\t<true/>\n'
                  '\t\t<key>NSAllowsArbitraryLoadsForMedia</key>\n\t\t<true/>\n\t</dict>\n')
    if 'ITSAppUsesNonExemptEncryption' not in s:
        extra += '\t<key>ITSAppUsesNonExemptEncryption</key>\n\t<false/>\n'
    if 'UIBackgroundModes' not in s:
        extra += '\t<key>UIBackgroundModes</key>\n\t<array>\n\t\t<string>audio</string>\n\t</array>\n'
    i = s.rfind('</dict>')
    s = s[:i] + extra + s[i:]
    p.write_text(s)
    print('patched', p)

pod = root / 'ios/Podfile'
if pod.exists():
    s = pod.read_text()
    s = re.sub(r"^#?\s*platform :ios, '[\d.]+'", "platform :ios, '13.0'", s, flags=re.M)
    pod.write_text(s)
    print('patched', pod)

pbx = root / 'ios/Runner.xcodeproj/project.pbxproj'
if pbx.exists():
    s = pbx.read_text()
    s = re.sub(r'IPHONEOS_DEPLOYMENT_TARGET = [\d.]+;', 'IPHONEOS_DEPLOYMENT_TARGET = 13.0;', s)
    pbx.write_text(s)
    print('patched', pbx)

t = root / 'test/widget_test.dart'
if t.exists():
    t.unlink()
    print('removed', t)
